<section class="section section-soft"><div class="container narrow"><span class="eyebrow">Search</span><h1><?= $query !== '' ? 'Results for “' . e($query) . '”' : 'Find a product' ?></h1><form class="hero-search" action="/search" method="get"><input type="search" name="q" value="<?= e($query) ?>" placeholder="What are you looking to buy?"><button type="submit">Search</button></form></div></section>
<section class="section"><div class="container">
<?php if ($query === ''): ?><div class="empty-state"><p>Enter a product, category or feature to start searching.</p></div>
<?php elseif (empty($results)): ?><div class="empty-state"><h2>No products found</h2><p>Try a broader term or add products through the CMS.</p></div>
<?php else: ?><div class="product-grid"><?php foreach ($results as $product): ?><article class="product-card"><a class="product-image" href="/product/<?= e($product['slug']) ?>"><?php if ($product['main_image_url']): ?><img src="<?= e($product['main_image_url']) ?>" alt="<?= e($product['display_title'] ?: $product['title']) ?>" loading="lazy"><?php else: ?><span class="image-placeholder">Product image</span><?php endif; ?></a><div class="card-body"><?php if ($product['best_for_label']): ?><span class="badge"><?= e($product['best_for_label']) ?></span><?php endif; ?><h3><a href="/product/<?= e($product['slug']) ?>"><?= e($product['display_title'] ?: $product['title']) ?></a></h3><?php if ($product['custom_score'] !== null): ?><div class="score">MediaPitch score <strong><?= e((string) $product['custom_score']) ?>/10</strong></div><?php endif; ?><a class="button button-secondary" href="/product/<?= e($product['slug']) ?>">View product</a></div></article><?php endforeach; ?></div><?php endif; ?>
</div></section>
